import type { Product } from "~/lib/types";
import holidaySetsFile from "~/data/holiday-sets.json";
import holidayHiddenFile from "~/data/holiday-hidden-products.json";

/**
 * The holiday page data, read from two checked-in JSON files:
 *
 *   src/data/holiday-sets.json             the three owner-approved sets, in
 *                                          page order, membership by product id
 *   src/data/holiday-hidden-products.json  products with no Amazon buy box that
 *                                          must not render as cards
 *
 * Both are generated by scripts/build-holiday-sets.mjs from the verified
 * curation file. Nothing here is hand-typed, and no route hardcodes an id.
 */

export type HolidaySetDef = {
  id: string;
  title: string;
  intro: string;
  productIds: number[];
};

export const HOLIDAY_SETS: HolidaySetDef[] = holidaySetsFile.sets as HolidaySetDef[];

/** Ids with no Amazon buy box on the verification date. */
export const HOLIDAY_HIDDEN_IDS: number[] = holidayHiddenFile.hidden.map((row) => Number(row.id));

const hiddenIds = new Set(HOLIDAY_HIDDEN_IDS);

/**
 * Drop the unbuyable products from a holiday product list. They stay active in
 * the catalog and stay in room=holiday, so they return by themselves the moment
 * Amazon restores stock and the data file is regenerated.
 */
export function hideUnbuyableHolidayProducts(products: Product[]): Product[] {
  return products.filter((product) => !hiddenIds.has(Number(product.id)));
}

export type ResolvedHolidaySet = {
  id: string;
  title: string;
  intro: string;
  products: Product[];
};

export type ResolvedHolidayPage = {
  sets: ResolvedHolidaySet[];
  more: Product[];
  /** Ids named in the sets file that the catalog no longer returns. */
  missing: { setId: string; id: number }[];
};

/**
 * Split a holiday product list into the three sets (each rendered in the order
 * the sets file gives) and everything left over for "More Christmas Finds".
 * A set id the catalog no longer returns is skipped rather than rendered empty,
 * and reported so the build output shows it.
 */
export function resolveHolidayPage(products: Product[]): ResolvedHolidayPage {
  const visible = hideUnbuyableHolidayProducts(products);
  const byId = new Map(visible.map((product) => [Number(product.id), product]));
  const used = new Set<number>();
  const missing: { setId: string; id: number }[] = [];

  const sets = HOLIDAY_SETS.map((set) => {
    const items: Product[] = [];
    for (const rawId of set.productIds) {
      const id = Number(rawId);
      used.add(id);
      const product = byId.get(id);
      if (!product) {
        missing.push({ setId: set.id, id });
        continue;
      }
      items.push(product);
    }
    return { id: set.id, title: set.title, intro: set.intro, products: items };
  });

  for (const miss of missing) {
    console.warn(
      `[holiday] set "${miss.setId}" names product id ${miss.id}, which the catalog does not return. Skipped.`,
    );
  }

  const more = visible.filter((product) => !used.has(Number(product.id)));
  return { sets, more, missing };
}
